SELECT id, account_id, txn_time, merchant, is_flagged, LEAD(amount, 1) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS next_amount, NTILE(3) OVER w_running AS amount_bucket, AVG(amount) OVER w_part AS amount_avg_6_prior, DENSE_RANK() OVER (ORDER BY amount DESC) AS amount_dense_rank, AVG(amount) OVER (ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5 FROM transactions WINDOW w_running AS (PARTITION BY MONTH(txn_time), txn_type ORDER BY amount, id), w_part AS (PARTITION BY TO_DATE(txn_time), txn_type ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING);
